/* One-time migration from Chirpy's old cache-first worker. Keep this URL. */
self.addEventListener('install', (event) => {
  event.waitUntil(self.skipWaiting());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const scope = self.registration.scope;
    const keys = await caches.keys();
    await Promise.all(keys.filter((key) => key.startsWith('chirpy-')).map(async (key) => {
      const cache = await caches.open(key);
      // Only remove this site's cache, not caches belonging to other projects.
      if (await cache.match(scope, { ignoreSearch: true })) {
        await caches.delete(key);
      }
    }));
    await self.clients.claim();
    await self.registration.unregister();
  })());
});

// Existing open tabs may remain controlled until their next navigation.
// While they do, revalidate with the network and never use Cache Storage.
self.addEventListener('fetch', (event) => {
  event.respondWith(fetch(event.request, { cache: 'no-cache' }));
});
